The ChatRoom is the subject and each connected member session is an observer. When a message is posted, the room notifies all observers except the sender; offline users are skipped and fetch later.
```csharp
public interface IMessageObserver { void OnMessage(Message m); }
public class ChatRoom {
    private readonly List<IMessageObserver> _observers = new();
    public void Join(IMessageObserver o) => _observers.Add(o);
    public void Leave(IMessageObserver o) => _observers.Remove(o);
    public void Post(Message m) {
        foreach (var o in _observers) o.OnMessage(m);
    }
}
```

Define an ISplitStrategy that validates input and returns the amount per user; ExpenseService picks a strategy by SplitType, so new types are added without changing the service.
```csharp
public interface ISplitStrategy {
    Dictionary<string, decimal> Split(decimal total, IReadOnlyList<SplitInput> inputs);
}
public class PercentSplit : ISplitStrategy {
    public Dictionary<string, decimal> Split(decimal total, IReadOnlyList<SplitInput> inputs) {
        if (inputs.Sum(i => i.Value) != 100m) throw new ArgumentException("Must total 100%");
        return inputs.ToDictionary(i => i.UserId, i => Math.Round(total * i.Value / 100m, 2));
    }
}
```

Net balance is what a user paid minus their share of every expense; positive means they should receive money.
```csharp
public Dictionary<string, decimal> NetBalances(IEnumerable<Expense> expenses) {
    var net = new Dictionary<string, decimal>();
    foreach (var e in expenses) {
        net[e.PaidBy] = net.GetValueOrDefault(e.PaidBy) + e.Amount;
        foreach (var s in e.Splits)
            net[s.UserId] = net.GetValueOrDefault(s.UserId) - s.Amount;
    }
    return net;
}
```

Hold seats atomically so either all requested seats are held or none are, with an expiry time.
```csharp
private readonly object _gate = new();
public bool TryHold(Show show, IList<string> seatIds, string userId) {
    lock (_gate) {
        var seats = seatIds.Select(id => show.Seats[id]).ToList();
        if (seats.Any(s => !s.IsAvailable(DateTime.UtcNow))) return false;
        foreach (var s in seats) s.Hold(userId, DateTime.UtcNow.AddMinutes(10));
        return true;
    }
}
```
In production, lock per show rather than globally, or push this to the DB or Redis.

The logger filters by level and fans out to every registered appender.
```csharp
public enum LogLevel { Debug, Info, Warn, Error }
public interface IAppender { void Append(LogLevel level, string msg); }
public class Logger {
    private readonly List<IAppender> _appenders = new();
    public LogLevel MinLevel { get; set; } = LogLevel.Info;
    public void AddAppender(IAppender a) => _appenders.Add(a);
    public void Log(LogLevel level, string msg) {
        if (level < MinLevel) return;
        foreach (var a in _appenders) a.Append(level, $"{DateTime.UtcNow:O} [{level}] {msg}");
    }
}
