A queue of timestamps is trimmed on each call; the lock keeps trim-check-add atomic.
```csharp
public class SlidingWindowLog {
    private readonly Queue<DateTime> _hits = new();
    private readonly int _limit; private readonly TimeSpan _window;
    public SlidingWindowLog(int limit, TimeSpan window) { _limit = limit; _window = window; }
    public bool TryAcquire(DateTime now) {
        lock (_hits) {
            while (_hits.Count > 0 && now - _hits.Peek() >= _window) _hits.Dequeue();
            if (_hits.Count >= _limit) return false;
            _hits.Enqueue(now); return true;
        }
    }
}
```

