Both files and directories are nodes; the directory delegates to children.
```csharp
public abstract class FsNode(string name) {
    public string Name { get; } = name;
    public abstract long GetSize();
}
public class FileNode(string name, long size) : FsNode(name) {
    public override long GetSize() => size;
}
public class DirectoryNode(string name) : FsNode(name) {
    private readonly Dictionary<string, FsNode> _children = new();
    public void Add(FsNode n) => _children.Add(n.Name, n);
    public override long GetSize() => _children.Values.Sum(c => c.GetSize());
}
```
